514	  function extractJSON(text) {
515	    // Find the data_preview marker first (both compact and spaced key formats)
516	    let m = text.indexOf('"type":"data_preview"');
517	    if (m === -1) m = text.indexOf('"type": "data_preview"');
518	    if (m === -1) return null;
519	
520	    // Bracket-counting helper: returns index of matching } for the { at start
521	    const matchingBrace = (t, s) => {
522	      let depth = 0, inStr = false, esc = false;
523	      for (let i = s; i < t.length; i++) {
524	        const c = t[i];
525	        if (esc) { esc = false; continue; }
526	        if (c === '\\' && inStr) { esc = true; continue; }
527	        if (c === '"') { inStr = !inStr; continue; }
528	        if (inStr) continue;
