// sanitizeJSON replaces non-standard JSON values the AI sometimes emits so that
// json.Unmarshal succeeds: NaN/Infinity → null, trailing commas removed,
// literal control characters inside strings escaped properly.
func sanitizeJSON(s string) string {
	s = strings.NewReplacer(
		": NaN", ": null",
		":NaN", ":null",
		": Infinity", ": null",
		":Infinity", ":null",
		": -Infinity", ": null",
		":-Infinity", ":null",
	).Replace(s)
	var out []byte
	inStr := false
	esc := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if esc {
			esc = false
			out = append(out, c)
			continue
		}
		if c == '\\' && inStr {
			esc = true
			out = append(out, c)
			continue
		}
		if c == '"' {
			inStr = !inStr
			out = append(out, c)
			continue
		}
		if inStr {
			// Escape literal control characters that are invalid in JSON strings
			switch c {
			case '\n':
				out = append(out, '\\', 'n')
				continue
			case '\r':
				out = append(out, '\\', 'r')
				continue
			case '\t':
				out = append(out, '\\', 't')
				continue
			default:
				if c < 0x20 {
					continue // drop other control chars
				}
			}
		} else {
			// Outside strings: strip trailing commas before } or ]
			if c == ',' {
				j := i + 1
				for j < len(s) && (s[j] == ' ' || s[j] == '\t' || s[j] == '\n' || s[j] == '\r') {
					j++
				}
				if j < len(s) && (s[j] == '}' || s[j] == ']') {
					continue
				}
			}
		}
		out = append(out, c)
	}
	return string(out)
}

