function extractJSON(text) {
  // Find the data_preview marker first (both compact and spaced key formats)
  let m = text.indexOf('"type":"data_preview"');
  if (m === -1) m = text.indexOf('"type": "data_preview"');
  if (m === -1) return null;

  // Bracket-counting helper: returns index of matching } for the { at start
  const matchingBrace = (t, s) => {
    let depth = 0, inStr = false, esc = false;
    for (let i = s; i < t.length; i++) {
      const c = t[i];
      if (esc) { esc = false; continue; }
      if (c === '\\' && inStr) { esc = true; continue; }
      if (c === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (c === '{') depth++;
      else if (c === '}') { depth--; if (depth === 0) return i; }

message.content:
This session is being continued from a previous conversation that ran out of context. The summary below covers the earlier portion of the conversation.

Summary:
1. Primary Request and Intent:
   Fix the Safecast AI assistant pages (`/assistant/` at localhost:8765 and simplemap.safecast.org/assistant/) so that `data_preview` JSON responses render as tables with CSV/Excel/JSON download buttons instead of raw JSON text. The map chat widget (map.html) is working and must NOT be changed. User requires local testing before any commit.

2. Key Technical Concepts:
   - SSE (Server-Sent Events) streaming: NDJSON lines, each a JSON chunk with `type`, `text`, `data_preview` fields
   - `data_preview` SSE event: Go server emits `{"type":"data_preview","data_preview":{...}}` so client renders a table
   - `extractDataPreview()` (Go): bracket-counting function that finds a `data_preview` JSON blob in AI response text
   - `extractJSON()` (JS): client-side equivalent, bracket-counting, used in `renderBotBubble()` and `finish()`
   - `sanitizeJSON()` (Go) / `sanitizeForParse()` (JS): clean NaN/Infinity/trailing commas/embedded newlines before JSON.parse
   - Three binaries: `safecast-new-map` (unified-server, port 8765), `safecast-web-chat` (port 3334), `safecast-mcp`
   - `/assistant/` at localhost:8765 → unified-server binary serving `cmd/unified-server/static/index.html`
   - `/assistant/` on production → web-chat binary on port 3334 serving `cmd/web-chat/index.html`
   - Map chat widget → `cmd/unified-server/public_html/map.html` (working, do NOT touch)
   - CloudFront buffering: web-chat detects CloudFront headers and buffers all chunks before flushing

3. Files and Code Sections:

   - **`cmd/web-chat/index.html`**
     - Fixed `finish()` handler to use `extractJSON()` instead of always calling `markdownToHTML`
     - Added shared `sanitizeForParse()` function
     - Added shared `extractJSON()` with bracket-counting algorithm
     - Replaced fragile inline JSON detection in `addMessage()` with `extractJSON()`
     - Added location string parsing fallback in `renderDataPreview()`
     ```js
     function sanitizeForParse(s) {
       let out = '', inStr = false, esc = false;
       for (let i = 0; i < s.length; i++) {
         const c = s[i];
         if (esc) { esc = false; out += c; continue; }
         if (c === '\\' && inStr) { esc = true; out += c; continue; }
         if (c === '"') { inStr = !inStr; out += c; continue; }
         if (inStr) {
           if (c === '\n') { out += '\\n'; continue; }
           if (c === '\r') { out += '\\r'; continue; }
           if (c === '\t') { out += '\\t'; continue; }
           if (c.charCodeAt(0) < 0x20) continue;
         } else {
           if (c === ',' && /^[ \t\r\n]*[}\]]/.test(s.slice(i + 1))) continue;
         }
         out += c;
       }
       return out
         .replace(/:[ \t]*NaN\b/g, ': null')
         .replace(/:[ \t]*Infinity\b/g, ': null')
         .replace(/:[ \t]*-Infinity\b/g, ': null');
     }

     function extractJSON(text) {
       let m = text.indexOf('"type":"data_preview"');
       if (m === -1) m = text.indexOf('"type": "data_preview"');
       if (m === -1) return null;
       const matchingBrace = (t, s) => {
         let depth = 0, inStr = false, esc = false;
         for (let i = s; i < t.length; i++) {
           const c = t[i];
           if (esc) { esc = false; continue; }
           if (c === '\\' && inStr) { esc = true; continue; }
           if (c === '"') { inStr = !inStr; continue; }
           if (inStr) continue;
           if (c === '{') depth++;
           else if (c === '}') { depth--; if (depth === 0) return i; }
         }
         return -1;
       };
       for (let i = 0; i < m; i++) {
         if (text[i] !== '{') continue;
         const end = matchingBrace(text, i);
         if (end !== -1 && end >= m) {
           const slice = text.slice(i, end + 1);
           try { return JSON.parse(slice); } catch (_) {
             try { return JSON.parse(sanitizeForParse(slice)); } catch (_) { continue; }
           }
         }
       }
       return null;
     }
     ```

   - **`cmd/unified-server/static/index.html`**
     - Replaced fragile `extractJSON` with bracket-counting version (same as web-chat)
     - Added `sanitizeForParse()` function (same logic)
     - Added location string regex fallback in `renderDataPreview()`
     ```js
     let mapUrl = row.map_link ||
       (row.latitude && row.longitude ? `...` : (row.lat && row.lon ? `...` : null));
     if (!mapUrl && row.location) {
       const m = String(row.location).match(/([-\d.]+)[°\s]*[Nn][,\s]+([-\d.]+)[°\s]*[Ee]/);
       if (m) mapUrl = `https://simplemap.safecast.org/?lat=${m[1]}&lon=${m[2]}&zoom=15`;
     }
     ```

   - **`cmd/unified-server/mcp_register.go`**
     - Added `sanitizeJSON()` function before `extractDataPreview()`
     - Updated `extractDataPreview()` to call `sanitizeJSON(candidate)` before `json.Unmarshal`
     - Returns sanitized JSON instead of raw candidate
     ```go
     func sanitizeJSON(s string) string {
       s = strings.NewReplacer(": NaN", ": null", ":NaN", ":null", ...).Replace(s)
       var out []byte
       inStr := false; esc := false
       for i := 0; i < len(s); i++ {
         c := s[i]
         if esc { esc = false; out = append(out, c); continue }
         if c == '\\' && inStr { esc = true; out = append(out, c); continue }
         if c == '"' { inStr = !inStr; out = append(out, c); continue }
         if inStr {
           switch c {
           case '\n': out = append(out, '\\', 'n'); continue
           case '\r': out = append(out, '\\', 'r'); continue
           case '\t': out = append(out, '\\', 't'); continue
           default: if c < 0x20 { continue }
           }
         } else {
           if c == ',' { /* trailing comma check */ }
         }
         out = append(out, c)
       }
       return string(out)
     }
     ```

   - **`cmd/web-chat/main.go`**
     - Added `DataPreview json.RawMessage` to `chunk` struct
     - Added `extractDataPreview()` function (same bracket-counting algorithm as mcp_register.go)
     - Added `sanitizeJSON()` function
     - Changed agentic loop final-turn handling to collect text blocks and call `extractDataPreview()` before sending chunks
     - Added `strings` import

